/**
 * Framework-free roving-tabindex toolbar controller (WAI-ARIA Toolbar pattern).
 *
 * - Finds elements with `role="button"` inside `container`.
 * - First button gets `tabindex="0"`, all others `-1`.
 * - ArrowRight / ArrowLeft navigate horizontally; ArrowDown / ArrowUp vertically
 *   (per `orientation`). Navigation wraps at both ends. Home / End jump to the
 *   first / last button.
 * - Clicking a button makes it the tab stop.
 * - A MutationObserver keeps state correct when buttons are added or removed:
 *   if the current tab stop disappears, the tab stop moves to the nearest
 *   surviving button (falling back to the first).
 */

export interface RovingHandle {
  /** Recompute the item list and repair tabindex values. */
  refresh(): void;
  /** Disconnect the MutationObserver and remove listeners. */
  destroy(): void;
  /** Current roving items (live query at call time). */
  items(): HTMLElement[];
  /** Index of the current tab stop, or -1 when there are no items. */
  currentIndex(): number;
}

export interface RovingOptions {
  /** 'horizontal' (default) uses Left/Right; 'vertical' uses Up/Down. */
  orientation?: "horizontal" | "vertical";
}

const ITEM_SELECTOR = '[role="button"]';

export function initRoving(
  container: HTMLElement,
  options: RovingOptions = {},
): RovingHandle {
  const orientation = options.orientation ?? "horizontal";

  const items = (): HTMLElement[] =>
    Array.from(container.querySelectorAll<HTMLElement>(ITEM_SELECTOR));

  let current: HTMLElement | null = null;

  function applyTabstops(): void {
    const list = items();
    // Drop stale reference if the node left the DOM or the container.
    if (current && !list.includes(current)) {
      const idx = Math.max(0, lastKnownIndex);
      current = null;
      pendingFocusIndex = idx;
    }
    if (list.length === 0) return;
    if (!current || !list.includes(current)) {
      const idx = Math.min(Math.max(pendingFocusIndex, 0), list.length - 1);
      current = list[idx];
      pendingFocusIndex = idx;
    }
    for (const el of list) {
      el.tabIndex = el === current ? 0 : -1;
    }
  }

  let pendingFocusIndex = 0;
  let lastKnownIndex = 0;

  function setCurrent(el: HTMLElement): void {
    const list = items();
    const idx = list.indexOf(el);
    if (idx === -1) return;
    lastKnownIndex = idx;
    pendingFocusIndex = idx;
    current = el;
    for (const item of list) {
      item.tabIndex = item === el ? 0 : -1;
    }
  }

  function move(delta: 1 | -1): void {
    const list = items();
    if (list.length === 0) return;
    const from = current ? list.indexOf(current) : 0;
    const next = (from + delta + list.length) % list.length;
    const target = list[next];
    setCurrent(target);
    target.focus();
  }

  function moveTo(index: number): void {
    const list = items();
    if (list.length === 0) return;
    const clamped = Math.min(Math.max(index, 0), list.length - 1);
    const target = list[clamped];
    setCurrent(target);
    target.focus();
  }

  function onKeyDown(event: KeyboardEvent): void {
    const forward =
      orientation === "horizontal" ? "ArrowRight" : "ArrowDown";
    const backward = orientation === "horizontal" ? "ArrowLeft" : "ArrowUp";
    switch (event.key) {
      case forward:
        event.preventDefault();
        move(1);
        break;
      case backward:
        event.preventDefault();
        move(-1);
        break;
      case "Home":
        event.preventDefault();
        moveTo(0);
        break;
      case "End":
        event.preventDefault();
        moveTo(items().length - 1);
        break;
      default:
        return;
    }
  }

  function onClick(event: MouseEvent): void {
    const target = (event.target as Element | null)?.closest<HTMLElement>(
      ITEM_SELECTOR,
    );
    if (target && container.contains(target)) setCurrent(target);
  }

  function onFocusIn(event: FocusEvent): void {
    // Sync state when focus enters an item by any means (e.g. Tab into toolbar).
    const target = (event.target as Element | null)?.closest<HTMLElement>(
      ITEM_SELECTOR,
    );
    if (target && container.contains(target)) setCurrent(target);
  }

  const observer = new MutationObserver(() => applyTabstops());
  observer.observe(container, { childList: true, subtree: true });

  container.addEventListener("keydown", onKeyDown);
  container.addEventListener("click", onClick);
  container.addEventListener("focusin", onFocusIn);

  applyTabstops();

  return {
    refresh: applyTabstops,
    destroy() {
      observer.disconnect();
      container.removeEventListener("keydown", onKeyDown);
      container.removeEventListener("click", onClick);
      container.removeEventListener("focusin", onFocusIn);
    },
    items,
    currentIndex() {
      const list = items();
      return current ? list.indexOf(current) : -1;
    },
  };
}

