 * - ArrowRight / ArrowLeft navigate horizontally; ArrowDown / ArrowUp vertically
 *   (per `orientation`). Navigation wraps at both ends. Home / End jump to the
 *   first / last button.
 * - Clicking or focusing a button makes it the tab stop.
 * - A MutationObserver keeps state correct when buttons are added or removed:
 *   if the current tab stop disappears, the tab stop moves to the button that
 *   now occupies its index (clamped), i.e. the nearest surviving neighbour.
 */

export interface RovingHandle {
  /** Recompute the item list and repair tabindex values. */
  refresh(): void;
  /** Disconnect the MutationObserver and remove listeners. */
  destroy(): void;
  /** Current roving items (live query at call time). */
  items(): HTMLElement[];
  /** Index of the current tab stop, or -1 when there are no items. */
  currentIndex(): number;
}

export interface RovingOptions {
  /** 'horizontal' (default) uses Left/Right; 'vertical' uses Up/Down. */
  orientation?: "horizontal" | "vertical";
}

const ITEM_SELECTOR = '[role="button"]';

export function initRoving(
  container: HTMLElement,
  options: RovingOptions = {},
): RovingHandle {
  const orientation = options.orientation ?? "horizontal";
  let index = 0;

  const items = (): HTMLElement[] =>
    Array.from(container.querySelectorAll<HTMLElement>(ITEM_SELECTOR));

  /** Re-apply tabindex values for the item currently at `index`. */
  function paint(): void {
    const list = items();
    if (list.length === 0) return;
    index = Math.min(Math.max(index, 0), list.length - 1);
    list.forEach((el, i) => {
      el.tabIndex = i === index ? 0 : -1;
    });
  }

  function setCurrent(el: HTMLElement): void {
    const idx = items().indexOf(el);
    if (idx === -1) return;
    index = idx;
    paint();
  }

  function move(delta: 1 | -1): void {
    const list = items();
    if (list.length === 0) return;
    paint(); // make sure `index` matches live DOM
    index = (index + delta + list.length) % list.length;
    paint();
    list[index].focus();
  }

  function moveTo(target: number): void {
    const list = items();
    if (list.length === 0) return;
    paint();
    index = Math.min(Math.max(target, 0), list.length - 1);
    paint();
    list[index].focus();
  }

  function onKeyDown(event: KeyboardEvent): void {
    const forward = orientation === "horizontal" ? "ArrowRight" : "ArrowDown";
    const backward = orientation === "horizontal" ? "ArrowLeft" : "ArrowUp";
    switch (event.key) {
      case forward:
        event.preventDefault();
        move(1);
        break;
      case backward:
        event.preventDefault();
        move(-1);
        break;
      case "Home":
        event.preventDefault();
        moveTo(0);
        break;
      case "End":
        event.preventDefault();
        moveTo(items().length - 1);
        break;
      default:
        break;
    }
  }

  function itemFromEventTarget(target: EventTarget | null): HTMLElement | null {
    const el =
      target instanceof Element
        ? target.closest<HTMLElement>(ITEM_SELECTOR)
        : null;
    return el && container.contains(el) ? el : null;
  }

  function onClick(event: MouseEvent): void {
    const item = itemFromEventTarget(event.target);
    if (item) setCurrent(item);
  }

  function onFocusIn(event: FocusEvent): void {
    const item = itemFromEventTarget(event.target);
    if (item) setCurrent(item);
  }

  const observer = new MutationObserver(() => {
    const list = items();
    // If the tab-stop holder was removed, `index` now points at whatever
    // took its place (or clamps to the last remaining item); repaint.
    if (list.length > 0 && !list[index]?.isConnected) paint();
    else paint();
  });
  observer.observe(container, { childList: true, subtree: true });

  container.addEventListener("keydown", onKeyDown);
  container.addEventListener("click", onClick);
  container.addEventListener("focusin", onFocusIn);

  paint();

  return {
    refresh: paint,
    destroy() {
      observer.disconnect();
      container.removeEventListener("keydown", onKeyDown);
      container.removeEventListener("click", onClick);
      container.removeEventListener("focusin", onFocusIn);
    },
    items,
    currentIndex() {
      const list = items();
      return list.length === 0 ? -1 : Math.min(index, list.length - 1);
    },
  };
}

