import { beforeEach, describe, expect, it } from "vitest";
import { initRoving } from "../src/roving";

function press(key: string, target: Element): KeyboardEvent {
  const event = new KeyboardEvent("keydown", { key, bubbles: true });
  target.dispatchEvent(event);
  return event;
}

function tabstops(container: HTMLElement): (0 | -1)[] {
  return Array.from(
    container.querySelectorAll<HTMLElement>('[role="button"]'),
  ).map((el) => el.tabIndex as 0 | -1);
}

let container: HTMLDivElement;

function buildToolbar(...labels: string[]): HTMLElement[] {
  labels.forEach((label) => {
    const btn = document.createElement("button");
    btn.setAttribute("role", "button");
    btn.textContent = label;
    container.appendChild(btn);
  });
  return Array.from(
    container.querySelectorAll<HTMLElement>('[role="button"]'),
  );
}

beforeEach(() => {
  document.body.innerHTML = "";
  container = document.createElement("div");
  container.setAttribute("role", "toolbar");
  document.body.appendChild(container);
});

describe("initRoving", () => {
  it("sets tabindex=0 on the first button and -1 on the rest", () => {
    const [a, b, c] = buildToolbar("A", "B", "C");
    initRoving(container);

    expect(tabstops(container)).toEqual([0, -1, -1]);
    expect(a!.tabIndex).toBe(0);
    expect(b!.tabIndex).toBe(-1);
    expect(c!.tabIndex).toBe(-1);
  });

  it("moves focus with ArrowRight / ArrowLeft without wrapping past ends until wrap is hit", () => {
    const buttons = buildToolbar("A", "B", "C");
    const handle = initRoving(container);

    buttons[0]!.focus();
    press("ArrowRight", buttons[0]);
    expect(document.activeElement).toBe(buttons[1]);
    expect(tabstops(container)).toEqual([-1, 0, -1]);

    press("ArrowRight", buttons[1]);
    expect(document.activeElement).toBe(buttons[2]);

    // Wrap-around: right from the last goes to the first.
    press("ArrowRight", buttons[2]);
    expect(document.activeElement).toBe(buttons[0]);
    expect(tabstops(container)).toEqual([0, -1, -1]);

    // Wrap-around: left from the first goes to the last.
    press("ArrowLeft", buttons[0]);
    expect(document.activeElement).toBe(buttons[2]);
    expect(tabstops(container)).toEqual([-1, -1, 0]);

    press("ArrowLeft", buttons[2]);
    expect(document.activeElement).toBe(buttons[1]);
    expect(handle.currentIndex()).toBe(1);
  });

  it("uses ArrowDown / ArrowUp when orientation is vertical", () => {
    const buttons = buildToolbar("A", "B");
    initRoving(container, { orientation: "vertical" });

    buttons[0]!.focus();
    // Left/Right must be inert in vertical mode.
    press("ArrowLeft", buttons[0]);
    expect(document.activeElement).toBe(buttons[0]);
    press("ArrowRight", buttons[0]);
    expect(document.activeElement).toBe(buttons[0]);

    press("ArrowDown", buttons[0]);
    expect(document.activeElement).toBe(buttons[1]);
    expect(tabstops(container)).toEqual([-1, 0]);

    press("ArrowUp", buttons[1]);
    expect(document.activeElement).toBe(buttons[0]);

    // Vertical wrap: Up from first -> last.
    press("ArrowUp", buttons[0]);
    expect(document.activeElement).toBe(buttons[1]);
  });

  it("supports Home and End", () => {
    const buttons = buildToolbar("A", "B", "C");
    initRoving(container);

    buttons[0]!.focus();
    press("End", buttons[0]);
    expect(document.activeElement).toBe(buttons[2]);
    expect(tabstops(container)).toEqual([-1, -1, 0]);

    press("Home", buttons[2]);
    expect(document.activeElement).toBe(buttons[0]);
    expect(tabstops(container)).toEqual([0, -1, -1]);
  });

  it("keeps tab stop valid when the focused button is removed from the DOM", async () => {
    const buttons = buildToolbar("A", "B", "C");
    initRoving(container);

    buttons[1]!.focus();
    press("ArrowRight", buttons[1]); // now on C
    expect(document.activeElement).toBe(buttons[2]);

    // Remove the current tab-stop holder.
    buttons[2]!.remove();

    // MutationObserver is async: wait a microtask/task for it to fire.
    await new Promise((resolve) => setTimeout(resolve, 0));

    expect(tabstops(container)).toEqual([-1, 0]);
    expect(document.querySelector('[role="button"]')?.tabIndex).toBe(-1);
    const remaining = container.querySelectorAll<HTMLElement>('[role="button"]');
    expect(remaining[1]!.tabIndex).toBe(0); // B inherits the tab stop

    // Navigation still works on the surviving set.
    remaining[1]!.focus();
    press("ArrowRight", remaining[1]); // wraps to A
    expect(document.activeElement).toBe(remaining[0]);
    expect(tabstops(container)).toEqual([0, -1]);
  });

  it("refresh() also repairs state after removal (manual path)", () => {
